def p(text):return dict(type='paragraph',text=text)
def eq(identifier):return dict(type='equation',id=identifier)
def table(headers,rows):return dict(type='table',headers=headers,rows=rows)
def items(*values):return dict(type='list',items=list(values))
def figure(number,file,caption,width_mm=170):return dict(type='figure',number=number,file='report/assets/'+file,caption=caption,width_mm=width_mm)
def page(title,*blocks,level=2):return dict(title=title,level=level,blocks=list(blocks))


